def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 700    # OPT_PARAM: {'initial': 700, 'min': 100, 'max': 3000, 'type': 'float'}
    max_order = 220     # OPT_PARAM: {'initial': 220, 'min': 1, 'max': 400, 'type': 'float'}
    est_mean = 105.0    # OPT_PARAM: {'initial': 105.0, 'min': 20.0, 'max': 300.0, 'type': 'float'}

    # Current inventory position (on-hand + entire pipeline)
    current_position = on_hand_inventory + sum(pipeline_orders)

    # Conservative target: at least a base-stock, but also at least the estimated lead-demand
    L = len(pipeline_orders) if pipeline_orders is not None else 0
    lead_demand_est = est_mean * L

    # Add a small safety buffer (half a period of demand)
    safety_buffer = 0.5 * est_mean

    target = int(round(max(base_stock, lead_demand_est + safety_buffer)))

    order_amount = max(0, int(round(target - current_position)))
    if order_amount > int(max_order):
        order_amount = int(max_order)
    return order_amount

